// F-188
//! Extractors for handler arguments. Used both by code generated by `#[veil::route]` and by hand-written handlers.

use super::request::Request;
use super::response::Response;
use super::schema::ValidationErrors;
use bytes::Bytes;
use serde_json::Value;
use std::sync::Arc;

pub use super::response::Json;

/// Deserializes the whole query string (`?page=1&q=x` into `T`). Validated automatically.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Query<T>(pub T);

/// An `application/x-www-form-urlencoded` or `multipart/form-data` body (file parts are ignored). Validated
/// automatically.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Form<T>(pub T);

/// Shared state registered with `App::state`.
#[derive(Debug)]
pub struct State<T>(pub Arc<T>);

impl<T> Clone for State<T> {
    fn clone(&self) -> Self {
        State(self.0.clone())
    }
}

/// The raw body.
pub type Body = Bytes;

/// All request headers, in the order received.
#[derive(Debug, Clone)]
pub struct Headers(pub Arc<Vec<(Bytes, Bytes)>>);

macro_rules! deref {
    ($($t:ident),*) => {$(
        impl<T> std::ops::Deref for $t<T> {
            type Target = T;
            fn deref(&self) -> &T { &self.0 }
        }
    )*};
}
deref!(Query, Form);

impl<T> std::ops::Deref for State<T> {
    type Target = T;
    fn deref(&self) -> &T {
        &self.0
    }
}

impl Headers {
    /// Returns a header value as a UTF-8 string (the name is case-insensitive). `None` if it is absent or not UTF-8.
    pub fn get(&self, name: &str) -> Option<&str> {
        self.0
            .iter()
            .find(|(n, _)| n.eq_ignore_ascii_case(name.as_bytes()))
            .and_then(|(_, v)| std::str::from_utf8(v).ok())
    }
}

/// Extracts a value from a request (returning the response to send on failure).
pub trait FromRequest: Sized {
    /// Extracts a value from `req`. On failure it returns, as `Err`, the response to send as is (400, 422 and so on).
    fn from_request(req: &Request) -> Result<Self, Response>;
}

// F-267
/// Extracts a value from a request asynchronously (for extractors that look up state, call a dependency container or
/// verify a token with I/O). Every [`FromRequest`] type is also a `FromRequestAsync`.
///
/// `#[veil::route]` uses it for arguments marked `#[inject]` and for the extractor types of `veil-proxy-kit`
/// (`Dep<T>`, `Auth<T>`, `CookieJar`, `BackgroundTasks` and so on). The future runs on the worker that handles the
/// request, so it does not need to be `Send`.
pub trait FromRequestAsync: Sized {
    /// Extracts a value from `req`; `Err` is the response to send as is.
    fn from_request_async(
        req: &Request,
    ) -> impl std::future::Future<Output = Result<Self, Response>>;
}

impl<T: FromRequest> FromRequestAsync for T {
    fn from_request_async(
        req: &Request,
    ) -> impl std::future::Future<Output = Result<Self, Response>> {
        std::future::ready(T::from_request(req))
    }
}

impl FromRequest for Request {
    fn from_request(req: &Request) -> Result<Self, Response> {
        Ok(req.clone())
    }
}

impl FromRequest for Bytes {
    fn from_request(req: &Request) -> Result<Self, Response> {
        Ok(req.body.clone())
    }
}

impl FromRequest for String {
    fn from_request(req: &Request) -> Result<Self, Response> {
        String::from_utf8(req.body.to_vec()).map_err(|_| {
            single_error(
                "body",
                None,
                "string_unicode",
                "Input should be a valid UTF-8 string",
            )
        })
    }
}

impl FromRequest for Headers {
    fn from_request(req: &Request) -> Result<Self, Response> {
        Ok(Headers(std::sync::Arc::new(req.headers.clone())))
    }
}

impl<T: Send + Sync + 'static> FromRequest for State<T> {
    fn from_request(req: &Request) -> Result<Self, Response> {
        req.state::<T>().map(State).ok_or_else(|| {
            Response::error(
                500,
                &format!(
                    "state of type {} is not registered (App::state)",
                    std::any::type_name::<T>()
                ),
            )
        })
    }
}

/// A 422 response carrying a single error.
pub(crate) fn single_error(location: &str, name: Option<&str>, kind: &str, msg: &str) -> Response {
    let mut e = ValidationErrors::default();
    let mut loc = vec![Value::from(location)];
    if let Some(n) = name {
        loc.push(Value::from(n));
    }
    e.push(&loc, kind, msg);
    e.into_response()
}

/// Extracts a path parameter with `FromStr` (failure gives 422 with `loc = ["path", name]`).
pub fn path_param<T: std::str::FromStr>(req: &Request, name: &str) -> Result<T, Response> {
    let raw = req
        .param(name)
        .ok_or_else(|| single_error("path", Some(name), "missing", "Field required"))?;
    raw.parse::<T>().map_err(|_| {
        single_error(
            "path",
            Some(name),
            "parsing",
            &format!("Input should be a valid {}", type_label::<T>()),
        )
    })
}

/// A required query parameter (absence or a conversion failure gives 422 with `loc = ["query", name]`).
pub fn query_param<T: std::str::FromStr>(req: &Request, name: &str) -> Result<T, Response> {
    match query_param_opt::<T>(req, name)? {
        Some(v) => Ok(v),
        None => Err(single_error(
            "query",
            Some(name),
            "missing",
            "Field required",
        )),
    }
}

/// An optional query parameter.
pub fn query_param_opt<T: std::str::FromStr>(
    req: &Request,
    name: &str,
) -> Result<Option<T>, Response> {
    match req.query_param(name) {
        None => Ok(None),
        Some(raw) => raw.parse::<T>().map(Some).map_err(|_| {
            single_error(
                "query",
                Some(name),
                "parsing",
                &format!("Input should be a valid {}", type_label::<T>()),
            )
        }),
    }
}

// B-418: JSON の本文は Content-Type が JSON のときだけ読む。以前は型を見ずに読み、CORS の事前確認の要らない
// 別サイトからの要求（`enctype="text/plain"` のフォーム、型の無い Blob を送る `fetch`・`sendBeacon`）が利用者の
// Cookie を付けて JSON のハンドラを動かせた（FastAPI の CVE-2021-32677 と同じ。axum の `Json` も 415）
/// Whether a `Content-Type` value names JSON: `application/json` or `application/*+json` (parameters are ignored).
pub fn is_json_content_type(ct: Option<&str>) -> bool {
    let Some(ct) = ct else { return false };
    let media = ct.split(';').next().unwrap_or("").trim();
    let Some((ty, sub)) = media.split_once('/') else {
        return false;
    };
    let sub = sub.as_bytes();
    ty.eq_ignore_ascii_case("application")
        && (sub.eq_ignore_ascii_case(b"json")
            || (sub.len() > 5 && sub[sub.len() - 5..].eq_ignore_ascii_case(b"+json")))
}

/// Deserializes a JSON body (a JSON syntax or type error gives 422, as in FastAPI). The request's `Content-Type`
/// must be `application/json` or `application/*+json`; another or a missing one gives 415, so that a cross-site form
/// or `fetch` that skips the CORS preflight cannot reach the handler.
pub fn json_body<T: serde::de::DeserializeOwned>(req: &Request) -> Result<T, Response> {
    if req.body.is_empty() {
        return Err(single_error("body", None, "missing", "Field required"));
    }
    if !is_json_content_type(req.header("content-type")) {
        return Err(Response::error(
            415,
            "Content-Type must be application/json",
        ));
    }
    serde_json::from_slice::<T>(&req.body).map_err(|e| {
        let kind = if e.is_syntax() || e.is_eof() {
            "json_invalid"
        } else {
            "model_attributes_type"
        };
        single_error("body", None, kind, &e.to_string())
    })
}

/// Deserializes the whole query string into `T`.
pub fn query_struct<T: serde::de::DeserializeOwned>(req: &Request) -> Result<T, Response> {
    serde_urlencoded::from_bytes::<T>(&req.query)
        .map_err(|e| single_error("query", None, "value_error", &e.to_string()))
}

// F-266: multipart も受ける
/// Deserializes a form body into `T` (`multipart/form-data` too: its non-file fields).
pub fn form_body<T: serde::de::DeserializeOwned>(req: &Request) -> Result<T, Response> {
    if super::multipart::is_multipart(req) {
        return super::multipart::multipart_form(req);
    }
    serde_urlencoded::from_bytes::<T>(&req.body)
        .map_err(|e| single_error("body", None, "value_error", &e.to_string()))
}

fn type_label<T>() -> &'static str {
    let n = std::any::type_name::<T>();
    match n {
        "i8" | "i16" | "i32" | "i64" | "i128" | "isize" | "u8" | "u16" | "u32" | "u64" | "u128"
        | "usize" => "integer",
        "f32" | "f64" => "number",
        "bool" => "boolean",
        _ => n.rsplit("::").next().unwrap_or(n),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn param_and_query_extraction() {
        let req = Request::new("GET", "/x?page=2&bad=z", vec![], "")
            .with_params(vec![(Arc::from("id"), Bytes::from_static(b"7"))]);
        assert_eq!(path_param::<u32>(&req, "id").unwrap(), 7);
        assert_eq!(query_param::<u32>(&req, "page").unwrap(), 2);
        assert_eq!(query_param_opt::<u32>(&req, "none").unwrap(), None);
        let r = query_param::<u32>(&req, "bad").unwrap_err();
        assert_eq!(r.status_code(), 422);
        let v: Value = serde_json::from_slice(r.body()).unwrap();
        assert_eq!(v["detail"][0]["loc"], serde_json::json!(["query", "bad"]));
        assert_eq!(v["detail"][0]["msg"], "Input should be a valid integer");
        assert_eq!(
            query_param::<u32>(&req, "missing")
                .unwrap_err()
                .status_code(),
            422
        );
    }

    #[test]
    fn json_body_errors_are_422() {
        let ct = || {
            vec![(
                Bytes::from_static(b"content-type"),
                Bytes::from_static(b"application/json"),
            )]
        };
        let req = Request::new("POST", "/x", ct(), "{bad");
        let r = json_body::<Value>(&req).unwrap_err();
        assert_eq!(r.status_code(), 422);
        let req = Request::new("POST", "/x", ct(), "{\"a\": 1}");
        assert_eq!(json_body::<Value>(&req).unwrap()["a"], 1);
    }

    // B-418: JSON 以外・無い Content-Type は 415（別サイトの text/plain のフォーム・型の無い Blob の fetch を断る）
    #[test]
    fn json_body_requires_a_json_content_type() {
        let req = |ct: Option<&'static str>| {
            let headers = ct
                .map(|v| {
                    vec![(
                        Bytes::from_static(b"content-type"),
                        Bytes::from_static(v.as_bytes()),
                    )]
                })
                .unwrap_or_default();
            Request::new("POST", "/x", headers, "{\"a\": 1}")
        };
        for ok in [
            "application/json",
            "Application/JSON; charset=utf-8",
            "application/merge-patch+json",
            "application/vnd.api+JSON",
        ] {
            assert_eq!(json_body::<Value>(&req(Some(ok))).unwrap()["a"], 1, "{ok}");
        }
        for bad in [
            None,
            Some("text/plain"),
            Some("text/plain; charset=utf-8"),
            Some("application/x-www-form-urlencoded"),
            Some("multipart/form-data; boundary=x"),
            Some("application/jsonx"),
            Some("application/+json"),
            Some("text/json"),
            Some(""),
        ] {
            assert_eq!(
                json_body::<Value>(&req(bad)).unwrap_err().status_code(),
                415,
                "{bad:?}"
            );
        }
        // 本文が無ければ従来どおり 422（必須の本文の欠け）
        let empty = Request::new("POST", "/x", vec![], "");
        assert_eq!(json_body::<Value>(&empty).unwrap_err().status_code(), 422);
    }
}
